from functools import lru_cache

def count_digit_one(n):
    s = str(n)
    @lru_cache(None)
    def go(i, tight, cnt):
        if i == len(s):
            return cnt
        hi = int(s[i]) if tight else 9
        return sum(go(i + 1, tight and d == hi, cnt + (d == 1)) for d in range(hi + 1))
    return go(0, True, 0)

