long long countDigitOne(long long n) {
    long long total = 0;
    for (long long p = 1; p <= n; p *= 10) { long long high = n / (p * 10), cur = n / p % 10, low = n % p;
        total += high * p + (cur > 1 ? p : cur == 1 ? low + 1 : 0); }
    return total;
}
